class Solution {
public:
    vector<int> assignTasks(vector<int>& servers, vector<int>& tasks) {
        int n = servers.size(), m = tasks.size();
        using Server = pair<int, int>;
        priority_queue<Server, vector<Server>, greater<Server>> free;
        for (int i = 0; i < n; ++i) free.push({servers[i], i});

        using BusyServer = tuple<long long, int, int>;
        priority_queue<BusyServer, vector<BusyServer>, greater<BusyServer>> busy;

        vector<int> ans;
        ans.reserve(m);
        long long currTime = 0;

        for (int i = 0; i < m; ++i) {
            currTime = max(currTime, (long long)i);
            if (free.empty() && get<0>(busy.top()) > currTime) {
                currTime = get<0>(busy.top());
            }
            while (!busy.empty() && get<0>(busy.top()) <= currTime) {
                auto [freeTime, w, sIdx] = busy.top();
                busy.pop();
                free.push({w, sIdx});
            }

            auto [w, sIdx] = free.top();
            free.pop();
            ans.push_back(sIdx);
            busy.push({currTime + tasks[i], w, sIdx});
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] assignTasks(int[] servers, int[] tasks) {
        int n = servers.length, m = tasks.length;
        PriorityQueue<int[]> free = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });
        for (int i = 0; i < n; ++i) free.offer(new int[]{servers[i], i});

        PriorityQueue<long[]> busy = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return Long.compare(a[0], b[0]);
            if (a[1] != b[1]) return Long.compare(a[1], b[1]);
            return Long.compare(a[2], b[2]);
        });

        int[] ans = new int[m];
        long currTime = 0;

        for (int i = 0; i < m; ++i) {
            currTime = Math.max(currTime, (long)i);
            if (free.isEmpty() && busy.peek()[0] > currTime) {
                currTime = busy.peek()[0];
            }
            while (!busy.isEmpty() && busy.peek()[0] <= currTime) {
                long[] b = busy.poll();
                free.offer(new int[]{(int)b[1], (int)b[2]});
            }

            int[] top = free.poll();
            ans[i] = top[1];
            busy.offer(new long[]{currTime + tasks[i], top[0], top[1]});
        }
        return ans;
    }
}

/**
 * @param {number[]} servers
 * @param {number[]} tasks
 * @return {number[]}
 */
var assignTasks = function(servers, tasks) {
    const n = servers.length, m = tasks.length;

    const freePq = [];
    const pushFree = (item) => {
        freePq.push(item);
        let idx = freePq.length - 1;
        while (idx > 0) {
            const p = Math.floor((idx - 1) / 2);
            if (freePq[p][0] > freePq[idx][0] || (freePq[p][0] === freePq[idx][0] && freePq[p][1] > freePq[idx][1])) {
                [freePq[p], freePq[idx]] = [freePq[idx], freePq[p]];
                idx = p;
            } else break;
        }
    };
    const popFree = () => {
        if (freePq.length === 0) return null;
        const top = freePq[0];
        const last = freePq.pop();
        if (freePq.length > 0) {
            freePq[0] = last;
            let idx = 0;
            while (true) {
                let left = 2 * idx + 1, right = 2 * idx + 2, best = idx;
                if (left < freePq.length && (freePq[left][0] < freePq[best][0] || (freePq[left][0] === freePq[best][0] && freePq[left][1] < freePq[best][1]))) best = left;
                if (right < freePq.length && (freePq[right][0] < freePq[best][0] || (freePq[right][0] === freePq[best][0] && freePq[right][1] < freePq[best][1]))) best = right;
                if (best !== idx) {
                    [freePq[idx], freePq[best]] = [freePq[best], freePq[idx]];
                    idx = best;
                } else break;
            }
        }
        return top;
    };

    const busyPq = [];
    const pushBusy = (item) => {
        busyPq.push(item);
        let idx = busyPq.length - 1;
        while (idx > 0) {
            const p = Math.floor((idx - 1) / 2);
            if (busyPq[p][0] > busyPq[idx][0] || (busyPq[p][0] === busyPq[idx][0] && (busyPq[p][1] > busyPq[idx][1] || (busyPq[p][1] === busyPq[idx][1] && busyPq[p][2] > busyPq[idx][2])))) {
                [busyPq[p], busyPq[idx]] = [busyPq[idx], busyPq[p]];
                idx = p;
            } else break;
        }
    };
    const popBusy = () => {
        if (busyPq.length === 0) return null;
        const top = busyPq[0];
        const last = busyPq.pop();
        if (busyPq.length > 0) {
            busyPq[0] = last;
            let idx = 0;
            while (true) {
                let left = 2 * idx + 1, right = 2 * idx + 2, best = idx;
                if (left < busyPq.length && (busyPq[left][0] < busyPq[best][0] || (busyPq[left][0] === busyPq[best][0] && (busyPq[left][1] < busyPq[best][1] || (busyPq[left][1] === busyPq[best][1] && busyPq[left][2] < busyPq[best][2]))))) best = left;
                if (right < busyPq.length && (busyPq[right][0] < busyPq[best][0] || (busyPq[right][0] === busyPq[best][0] && (busyPq[right][1] < busyPq[best][1] || (busyPq[right][1] === busyPq[best][1] && busyPq[right][2] < busyPq[best][2]))))) best = right;
                if (best !== idx) {
                    [busyPq[idx], busyPq[best]] = [busyPq[best], busyPq[idx]];
                    idx = best;
                } else break;
            }
        }
        return top;
    };

    for (let i = 0; i < n; ++i) pushFree([servers[i], i]);

    const ans = [];
    let currTime = 0;

    for (let i = 0; i < m; ++i) {
        currTime = Math.max(currTime, i);
        if (freePq.length === 0 && busyPq[0][0] > currTime) {
            currTime = busyPq[0][0];
        }
        while (busyPq.length > 0 && busyPq[0][0] <= currTime) {
            const [t, w, sIdx] = popBusy();
            pushFree([w, sIdx]);
        }

        const [w, sIdx] = popFree();
        ans.push(sIdx);
        pushBusy([currTime + tasks[i], w, sIdx]);
    }

    return ans;
};
